/**
 * Fleet Snowfluff — GIF cursor + typing droppings.
 * Generated by scripts/setup-vibrancy.ps1 (embeds assets as data URIs).
 */
(function () {
  'use strict';

  var CURSOR_GIF = '__FLEET_CURSOR_GIF_DATA_URI__';
  var DROP_SPRITES = __FLEET_DROPING_SPRITES_JSON__;
  var CURSOR_REF_LINE_HEIGHT = 19;
  var CURSOR_HEIGHT_RATIO = 32 / 19;
  var CURSOR_MIN_SIZE = 14;
  var CURSOR_MAX_SIZE = 160;
  var CURSOR_GAP_BASE = 2;
  var CURSOR_OFFSET_Y_BASE = 2;
  var MAX_PARTICLES = 24;
  var SPAWN_THROTTLE_MS = 80;
  var cursorRaf = 0;
  var particleRaf = 0;
  var particles = [];
  var editorParticles = typeof WeakMap !== 'undefined' ? new WeakMap() : null;
  var lastSpawnAt = typeof WeakMap !== 'undefined' ? new WeakMap() : null;
  var lastCompositionData = typeof WeakMap !== 'undefined' ? new WeakMap() : null;
  var editorObservers = typeof WeakMap !== 'undefined' ? new WeakMap() : null;

  if (!CURSOR_GIF || CURSOR_GIF.indexOf('__FLEET_') === 0) return;
  if (!DROP_SPRITES || !DROP_SPRITES.length) DROP_SPRITES = [];

  document.documentElement.classList.add('fleet-atmosphere-cursor');

  function pickDropSprite() {
    return DROP_SPRITES[Math.floor(Math.random() * DROP_SPRITES.length)];
  }

  function activeEditorFromTarget(target) {
    if (!target || !target.closest) return null;
    var ed = target.closest('.monaco-editor');
    if (!ed || ed.closest('.monaco-editor-overlaymessage')) return null;
    return ed;
  }

  function cursorNodes(editorRoot) {
    var layer = editorRoot.querySelector('.cursors-layer');
    if (!layer) return [];
    var nodes = layer.querySelectorAll('.cursor');
    if (!nodes.length) nodes = layer.querySelectorAll(':scope > div');
    return Array.prototype.filter.call(nodes, function (n) {
      return n.classList.contains('cursor') || n.style.height;
    });
  }

  function isEditorVisible(editorRoot) {
    var rect = editorRoot.getBoundingClientRect();
    return rect.width > 2 && rect.height > 2;
  }

  function cursorLayout(rect) {
    var lineH = rect.height;
    var scale = lineH / CURSOR_REF_LINE_HEIGHT;
    var size = Math.round(lineH * CURSOR_HEIGHT_RATIO);
    if (size < CURSOR_MIN_SIZE) size = CURSOR_MIN_SIZE;
    if (size > CURSOR_MAX_SIZE) size = CURSOR_MAX_SIZE;
    return {
      size: size,
      gap: Math.max(1, Math.round(CURSOR_GAP_BASE * scale)),
      offsetY: Math.max(1, Math.round(CURSOR_OFFSET_Y_BASE * scale))
    };
  }

  function syncCursorSprites(editorRoot) {
    var layer = editorRoot.querySelector('.cursors-layer');
    if (!layer) return;

    if (!isEditorVisible(editorRoot)) {
      layer.querySelectorAll('.fleet-cursor-sprite').forEach(function (sprite) {
        sprite.style.display = 'none';
      });
      return;
    }

    var cursors = cursorNodes(editorRoot);
    var layerRect = layer.getBoundingClientRect();
    var linked = new Set();

    if (!cursors.length) {
      layer.querySelectorAll('.fleet-cursor-sprite').forEach(function (sprite) {
        sprite.style.display = 'none';
      });
      return;
    }

    cursors.forEach(function (cursor) {
      var rect = cursor.getBoundingClientRect();
      if (rect.height <= 0) return;

      var sprite = cursor._fleetCursorSprite;
      if (!sprite) {
        sprite = document.createElement('img');
        sprite.className = 'fleet-cursor-sprite';
        sprite.src = CURSOR_GIF;
        sprite.draggable = false;
        sprite.alt = '';
        layer.appendChild(sprite);
        cursor._fleetCursorSprite = sprite;
      }

      linked.add(sprite);
      sprite.style.display = '';
      var layout = cursorLayout(rect);
      sprite.style.width = layout.size + 'px';
      sprite.style.height = layout.size + 'px';
      sprite.style.left = rect.left - layerRect.left + rect.width + layout.gap + 'px';
      sprite.style.top = rect.top - layerRect.top - layout.size + rect.height + layout.offsetY + 'px';
    });

    layer.querySelectorAll('.fleet-cursor-sprite').forEach(function (sprite) {
      if (!linked.has(sprite)) sprite.remove();
    });
  }

  function syncAllCursors() {
    cursorRaf = 0;
    document.querySelectorAll('.monaco-editor').forEach(syncCursorSprites);
  }

  function scheduleCursorSync() {
    if (cursorRaf) return;
    cursorRaf = requestAnimationFrame(syncAllCursors);
  }

  function ensureDropLayer(editorRoot) {
    var layer = editorRoot.querySelector('.fleet-drop-layer');
    if (layer) return layer;
    layer = document.createElement('div');
    layer.className = 'fleet-drop-layer';
    layer.setAttribute('aria-hidden', 'true');
    var host = editorRoot.querySelector('.overflow-guard') || editorRoot;
    host.appendChild(layer);
    return layer;
  }

  function particleCountFor(editorRoot) {
    if (!editorParticles) return particles.length;
    return editorParticles.get(editorRoot) || 0;
  }

  function setParticleCountFor(editorRoot, n) {
    if (editorParticles) editorParticles.set(editorRoot, n);
  }

  function spawnParticle(editorRoot, cursorIndex) {
    if (!DROP_SPRITES.length) return false;

    while (particleCountFor(editorRoot) >= MAX_PARTICLES) {
      var oldest = particles.shift();
      if (oldest && oldest.el) oldest.el.remove();
      if (oldest && oldest.editor) {
        setParticleCountFor(oldest.editor, Math.max(0, particleCountFor(oldest.editor) - 1));
      }
    }

    var cursors = cursorNodes(editorRoot);
    if (!cursors.length) return false;

    var idx = typeof cursorIndex === 'number' ? cursorIndex : 0;
    if (idx >= cursors.length) idx = 0;
    var cursor = cursors[idx];
    var cRect = cursor.getBoundingClientRect();
    var edRect = editorRoot.getBoundingClientRect();
    if (cRect.height <= 0) return false;

    var layout = cursorLayout(cRect);
    var layer = ensureDropLayer(editorRoot);
    var dropScale = cRect.height / CURSOR_REF_LINE_HEIGHT;
    var size = Math.round((14 + Math.random() * 12) * Math.max(0.75, dropScale));
    var img = document.createElement('img');
    img.className = 'fleet-drop-particle';
    img.src = pickDropSprite();
    img.draggable = false;
    img.alt = '';
    img.style.width = size + 'px';
    img.style.height = size + 'px';

    var x = cRect.left - edRect.left + cRect.width + layout.gap + Math.random() * 8;
    var y = cRect.top - edRect.top + cRect.height * 0.5 + Math.random() * 4;

    img.style.left = x + 'px';
    img.style.top = y + 'px';
    layer.appendChild(img);

    particles.push({
      el: img,
      editor: editorRoot,
      x: x,
      y: y,
      vx: (Math.random() - 0.45) * 1.4,
      vy: 0.4 + Math.random() * 1.2,
      life: 1,
      fade: 0.01 + Math.random() * 0.012
    });
    setParticleCountFor(editorRoot, particleCountFor(editorRoot) + 1);
    scheduleParticleTick();
    return true;
  }

  function shouldThrottleSpawn(editorRoot) {
    if (!lastSpawnAt) return false;
    var now = Date.now();
    var last = lastSpawnAt.get(editorRoot) || 0;
    if (now - last < SPAWN_THROTTLE_MS) return true;
    lastSpawnAt.set(editorRoot, now);
    return false;
  }

  function trySpawnParticle(editorRoot) {
    if (shouldThrottleSpawn(editorRoot)) return;
    spawnParticle(editorRoot);
  }

  function tickParticles() {
    particleRaf = 0;
    var alive = [];

    particles.forEach(function (p) {
      p.vy += 0.06;
      p.x += p.vx;
      p.y += p.vy;
      p.life -= p.fade;

      if (p.life <= 0 || !p.el.isConnected) {
        if (p.el.parentNode) p.el.remove();
        if (p.editor) {
          setParticleCountFor(p.editor, Math.max(0, particleCountFor(p.editor) - 1));
        }
        return;
      }

      p.el.style.left = p.x + 'px';
      p.el.style.top = p.y + 'px';
      p.el.style.opacity = String(Math.max(0, p.life));
      alive.push(p);
    });

    particles = alive;
    if (particles.length) scheduleParticleTick();
  }

  function scheduleParticleTick() {
    if (particleRaf) return;
    particleRaf = requestAnimationFrame(tickParticles);
  }

  function onTyping(e) {
    if (e.repeat) return;
    if (e.ctrlKey || e.metaKey || e.altKey) return;
    var ed = activeEditorFromTarget(e.target);
    if (!ed) return;

    if (e.isComposing) {
      scheduleCursorSync();
      return;
    }

    if (e.key && e.key.length === 1) {
      trySpawnParticle(ed);
    }
    scheduleCursorSync();
  }

  function onCompositionUpdate(e) {
    var ed = activeEditorFromTarget(e.target);
    if (!ed) return;

    var prev = lastCompositionData ? (lastCompositionData.get(ed) || '') : '';
    var next = e.data || '';
    if (lastCompositionData) lastCompositionData.set(ed, next);

    if (next && next !== prev) {
      trySpawnParticle(ed);
    }
    scheduleCursorSync();
  }

  function onCompositionEnd(e) {
    var ed = activeEditorFromTarget(e.target);
    if (!ed) return;
    if (lastCompositionData) lastCompositionData.set(ed, '');
    trySpawnParticle(ed);
    scheduleCursorSync();
  }

  function onEditorInput(e) {
    scheduleCursorSync();
    if (!e.isComposing) return;
    var ed = activeEditorFromTarget(e.target);
    if (!ed) return;
    trySpawnParticle(ed);
  }

  function bindEditor(editorRoot) {
    if (editorObservers && editorObservers.has(editorRoot)) return;
    ensureDropLayer(editorRoot);

    var mo = new MutationObserver(function () {
      scheduleCursorSync();
    });
    mo.observe(editorRoot, {
      subtree: true,
      childList: true,
      attributes: true,
      attributeFilter: ['class', 'style']
    });
    if (editorObservers) editorObservers.set(editorRoot, mo);

    var retries = 0;
    (function retryCursorLayer() {
      if (editorRoot.querySelector('.cursors-layer')) {
        scheduleCursorSync();
        return;
      }
      if (retries++ < 10) {
        setTimeout(retryCursorLayer, 40 * retries);
      }
    })();
  }

  function scanEditors() {
    document.querySelectorAll('.monaco-editor').forEach(bindEditor);
    scheduleCursorSync();
  }

  function onEditorActivated() {
    scheduleCursorSync();
    setTimeout(scheduleCursorSync, 0);
    setTimeout(scheduleCursorSync, 120);
  }

  new MutationObserver(function (mutations) {
    for (var i = 0; i < mutations.length; i++) {
      if (mutations[i].addedNodes.length) {
        scanEditors();
        return;
      }
    }
  }).observe(document.body, { childList: true, subtree: true });

  document.addEventListener('focusin', function (e) {
    if (activeEditorFromTarget(e.target)) onEditorActivated();
  }, true);

  document.addEventListener('mousedown', function (e) {
    if (e.target.closest('.monaco-editor') || e.target.closest('.tab')) onEditorActivated();
  }, true);

  document.addEventListener('wheel', function (e) {
    if (!(e.ctrlKey || e.metaKey)) return;
    if (e.target.closest('.monaco-editor')) onEditorActivated();
  }, { capture: true, passive: true });

  document.addEventListener('keydown', onTyping, true);
  document.addEventListener('compositionupdate', onCompositionUpdate, true);
  document.addEventListener('compositionend', onCompositionEnd, true);
  document.addEventListener('input', onEditorInput, true);
  document.addEventListener('keyup', scheduleCursorSync, true);
  document.addEventListener('mouseup', scheduleCursorSync, true);

  scanEditors();
})();
